                      <img className="w-180 h-109.5 inline max-w-full overflow-clip aspect-[auto_2048/1247] align-bottom max-md:w-[20.9375rem] max-md:h-51" data-component="image" alt="copyleaks Test mit Browser-Plugin" height="1247" sizes="(max-width: 2048px) 100vw, 2048px" src="/assets/cloned/images/b9b194821888.jpg" srcSet="/assets/cloned/images/b9b194821888.jpg 2048w, /assets/cloned/images/c39ac2116d2e.jpg 1024w, /assets/cloned/images/9ec1c602a8f8.jpg 768w" width="2048" />
