                        <img className="w-full h-[1.8125rem] block max-w-full grow shrink-0 basis-[0%] overflow-clip object-cover align-bottom max-md:h-[3.4375rem] md:max-lg:h-7" data-component="image" alt="100% mittels ChatGPT generierten Text eine 90,68%ig menschliche Bewertung" src="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7" />
